import re,os
REG={}
for l in open(os.path.join(os.path.dirname(__file__),"registry.txt")):
    p=[x.strip() for x in l.strip().split("|")]
    if len(p)==4: REG[p[0]]=dict(lic=p[1],pushed=p[2],stars=int(p[3]))
CUT="2026-04-12"
def permissive(l):
    return bool(re.match(r"(MIT|Apache-2\.0|BSD|CC0|ISC|MPL|Zlib)",l))
def verdict(repo,hint):
    r=REG[repo]; l=r["lic"]
    if "ARCHIVED" in l: return "Reject (archived)"
    if r["pushed"]<CUT: return "Reject (stale)"
    if l.startswith("CC-BY"): return "Reference only"
    if not permissive(l): return "Reference only"
    return {"A":"Adopt now","L":"Adopt later","R":"Reference only","X":"Reject"}[hint]
def row(repo,hint,use):
    r=REG[repo]
    return "| [%s](https://github.com/%s) | %s | %s | %s | %s | %s |"%(repo,repo,r["lic"],r["pushed"],r["stars"],verdict(repo,hint),use)
HDR="| Repo | Licence | Last push | Stars | Verdict | What it is and how Cyrus would use it |\n|---|---|---|---|---|---|"
def table(items):
    return HDR+"\n"+"\n".join(row(*i) for i in items)
EOF
